#include "bridge_memory_tracking.h"

#include <array>
#include <cassert>
#include <iostream>
#include <vector>

struct Allocation {
  Allocation* m_bridgePrev = nullptr;
  Allocation* m_bridgeNext = nullptr;
  unsigned refs = 1;
};

int main() {
  constexpr uint64_t mib = 1u << 20;
  for (uint64_t upstream : {4*mib, 8*mib, 16*mib, 32*mib, 64*mib}) {
    assert(dxvk::bridgeMappedChunkLimit(upstream, 0) == upstream);
    assert(dxvk::bridgeMappedChunkLimit(upstream, 16) == std::min(upstream, 16*mib));
    assert(dxvk::bridgeMappedChunkLimit(upstream, 64) == upstream);
    for (int32_t invalid : {-1, 1, 8, 17, 128, INT32_MAX}) {
      assert(!dxvk::bridgeValidMappedChunkSize(invalid));
      assert(dxvk::bridgeMappedChunkLimit(upstream, invalid) == upstream);
    }
  }

  dxvk::BridgeMemoryList<Allocation> list;
  std::array<Allocation, 256> nodes;
  for (auto& node : nodes) {
    list.add(&node);
  }
  // Cached slots remain registered when their external reference count is zero.
  for (auto& node : nodes) {
    node.refs = 0;
  }
  size_t cached = 0;
  for (auto* node = list.head(); node; node = node->m_bridgeNext) {
    assert(node->refs == 0);
    cached++;
  }
  assert(cached == nodes.size());

  // Return interleaved slots, including the head, tail and middle nodes.
  for (size_t i = 0; i < nodes.size(); i += 2) {
    list.remove(&nodes[i]);
    assert(!nodes[i].m_bridgeNext && !nodes[i].m_bridgePrev);
  }
  size_t count = 0;
  Allocation* previous = nullptr;
  for (auto* node = list.head(); node; node = node->m_bridgeNext) {
    assert(node->m_bridgePrev == previous);
    previous = node;
    count++;
  }
  assert(count == nodes.size()/2);
  for (size_t i = 1; i < nodes.size(); i += 2) {
    list.remove(&nodes[i]);
  }
  assert(!list.head());

  // Reuse storage across repeated load/unload cycles; no stale links may survive.
  for (unsigned cycle = 0; cycle < 100; cycle++) {
    for (auto& node : nodes) {
      node.refs = 1;
      list.add(&node);
    }
    while (auto* node = list.head()) {
      list.remove(node);
    }
    assert(!list.head());
  }
  std::cout << "PASS: baseline/cap policy, cached slots, arbitrary returns and storage reuse\n";
}
